import "./App.css";
import Stopwatch from "./Stopwatch.tsx";

function App() {
  const genders = ["m", "f", "nb"];
  return (
    <div className="App">
      {genders.map((gender) => (
        <Stopwatch genderId={gender} key={gender} />
      ))}
      <Stopwatch genderId="m" />
      <Stopwatch genderId="f" />
      <Stopwatch genderId="nb" />
    </div>
  );
}

export default App;
